-- Run time: 2026-11-10 21:47:37 HST
WITH session_steps AS ( SELECT session_id, ARRAY_AGG(browser IGNORE NULLS ORDER BY sequence_number LIMIT 1) [SAFE_OFFSET(0)] AS browser, MIN(IF(event_type = 'product', sequence_number, NULL)) AS product_step, MIN(IF(event_type = 'purchase', sequence_number, NULL)) AS purchase_step FROM `bigquery-public-data.thelook_ecommerce.events` WHERE event_type IN ('product', 'purchase') AND session_id IS NOT NULL GROUP BY session_id ) SELECT COALESCE(browser, 'Unknown') AS browser, COUNTIF(product_step IS NOT NULL) AS product_sessions, COUNTIF(product_step IS NOT NULL AND purchase_step > product_step) AS product_then_purchase_sessions, ROUND(100 * SAFE_DIVIDE( COUNTIF(product_step IS NOT NULL AND purchase_step > product_step), COUNTIF(product_step IS NOT NULL) ), 2) AS product_to_purchase_pct FROM session_steps GROUP BY browser ORDER BY product_to_purchase_pct;